SELECT recipient_cursor FROM kb_knowledge_match_projection WHERE event_id = #{claim.id}
    AND lease_owner = #{owner} AND claim_token = #{claim.token} AND status = 'PENDING'
    AND lease_until > clock_timestamp() FOR UPDATE

SELECT recipient_cursor FROM kb_knowledge_week WHERE week_start = #{claim.weekStart}
    AND lease_owner = #{owner} AND claim_token = #{claim.token} AND status <> 'DONE'
    AND lease_until > clock_timestamp() FOR UPDATE

SELECT id, user_id, kind, update_id, week_start, status, dispatch_position, dispatched_at
FROM kb_knowledge_delivery WHERE id = #{claim.id} AND lease_owner = #{owner} AND claim_token = #{claim.token}
    AND status = 'PENDING' AND lease_until > clock_timestamp() FOR UPDATE
